/* CTET Mock offline worker - generated by ctet-mock/build.py.
   Every asset below is precached so the library opens with no network. */
const VERSION = "74434ff9a6c0";
const CACHE_NAME = "ctet-mock-74434ff9a6c0";
const PRECACHE = [
  "./",
  "index.html",
  "app.css",
  "app.js",
  "player.html",
  "player.js",
  "manifest.webmanifest",
  "icons/icon-192.png",
  "icons/icon-512.png",
  "icons/icon-maskable-512.png",
  "icons/apple-touch-icon.png",
  "icons/favicon.png",
  "catalog.json",
  "mocks/p2-social-c8-natural-resources-m01.html",
];

// Assets that could not be cached, so the app can tell the learner which
// paper is not on the device.
let FAILED = [];

self.addEventListener("install", (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_NAME);
    // One unreachable file must not cancel the whole offline library.
    const results = await Promise.allSettled(
      PRECACHE.map((url) => cache.add(new Request(url, { cache: "reload" })))
    );
    FAILED = PRECACHE.filter((url, index) => results[index].status === "rejected");
    // The worker waits here: the page decides when to switch over, so the
    // "refresh" button in the app really refreshes.
  })());
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(
      names.filter((name) => name !== CACHE_NAME).map((name) => caches.delete(name))
    );
    await self.clients.claim();
  })());
});

self.addEventListener("fetch", (event) => {
  const request = event.request;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  event.respondWith(respond(request, url));
});

self.addEventListener("message", (event) => {
  const data = event.data || {};
  if (data.type === "SKIP_WAITING") self.skipWaiting();
  if (data.type === "CACHE_STATUS" && event.ports && event.ports[0]) {
    event.waitUntil((async () => {
      const cache = await caches.open(CACHE_NAME);
      const keys = await cache.keys();
      event.ports[0].postMessage({
        cached: keys.length,
        expected: PRECACHE.length,
        failed: FAILED
      });
    })());
  }
});

async function respond(request, url) {
  const cache = await caches.open(CACHE_NAME);
  const cached = await cache.match(request, { ignoreSearch: true });
  if (cached) return cached;
  try {
    const response = await fetch(request);
    if (response && response.status === 200 && response.type === "basic") {
      cache.put(request, response.clone());
    }
    return response;
  } catch (error) {
    // A paper that is not cached must fail, not show the library in its
    // place: the player needs to know it could not open the paper.
    const isPaper = url.pathname.indexOf("/mocks/") >= 0;
    if (request.mode === "navigate" && !isPaper) {
      const shell = await cache.match("index.html");
      if (shell) return shell;
    }
    throw error;
  }
}
